// StageOutput's typed attributes, generated by tools/node_attributes.py from node_definitions.usda: its
// inputs and properties, read by name, and its outputs, committed by name. Don't edit it: change the
// definition and run `uv run python tools/node_attributes.py render`.
#pragma once

#include <pxr/pxr.h>

#include "node_input_reader.h"
#include "node_roles.h"

namespace proscenium {

struct StageOutputInputs {
  static constexpr const char* kLayer = "inputs:layer";
  static constexpr const char* kCoordinateConversion = "props:coordinateConversion";

  LayerInput layer{};
  bool coordinateConversion{};
};

inline StageOutputInputs ReadStageOutputInputs(const NodeInputReader& reader) {
  StageOutputInputs inputs;
  inputs.layer = reader.Layer("inputs:layer");
  inputs.coordinateConversion = reader.Value<bool>("props:coordinateConversion");
  return inputs;
}

// What the node outputs; an output left empty, such as a null layer, commits nothing.
struct StageOutputOutputs {};

inline ValueOutputs WriteStageOutputOutputs(const StageOutputOutputs& outputs) {
  ValueOutputs values;
  static_cast<void>(outputs);
  return values;
}

}  // namespace proscenium
